let translations={},translationsReady=null;function initX(){const n=localStorage.getItem("lang")||"en";localStorage.setItem("lang",n),translationsReady=loadLanguage(n)}function loadLanguage(n){return fetch(`/assets/js/i18n/${n}.json`).then(n=>n.json()).then(n=>{translations=n,applyTranslations()}).catch(()=>console.error(`Language file "${n}.json" not found`))}function applyTranslations(){document.querySelectorAll("[i18n]").forEach(n=>{const t=n.getAttribute("i18n");n.textContent=translations[t]||t})}window.translateString=function(n){return translations[n]||n},window.translateStringAsync=async function(n){return await translationsReady,translations[n]||n},initX();